      "type": "string",
      "description": "The Salesforce ID of the Contact record under which the Case will be created (required)"
    },
    "Subject": {
      "type": "string",
      "description": "Subject or title of the Case (required)"
    },
    "Description": {
      "type": "string",
      "description": "Detailed description of the Case"
    },
    "Status": {
      "type": "string",
      "description": "Status of the Case (e.g., New, Working, Escalated, Closed)"
    },
    "Priority": {
      "type": "string",
      "description": "Priority level of the Case (e.g., Low, Medium, High)"
    },
    "Origin": {
      "type": "string",
      "description": "Origin of the Case (e.g., Phone, Email, Web, Chat)"
    },
    "Type": {
      "type": "string",
      "description": "Type of the Case (e.g., Problem, Feature Request, Question, Service Request)"
    },
    "Reason": {
      "type": "string",
      "description": "Reason for the Case"
    },
    "AccountId": {
      "type": "string",
      "description": "Salesforce ID of the related Account (auto-populated from Contact if not provided)"
    },
    "CaseId": {
      "type": "string",
      "description": "The Salesforce ID of the created Case record (returned in response)"
    },
    "CaseNumber": {
      "type": "string",
      "description": "Auto-generated Case number (returned in response)"
    }
  },
  "required": ["ContactId", "Subject"]
}

